#!/usr/bin/env bash
# Print the DKIM public key DNS record generated by the Rspamd container.
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd -- "$SCRIPT_DIR/.." && pwd)"
# shellcheck source=lib-env.sh
source "$SCRIPT_DIR/lib-env.sh"
cd "$ROOT_DIR"

load_env "$ROOT_DIR/.env"
: "${MAIL_DOMAIN:?MAIL_DOMAIN is required in .env}"

record_file="/var/lib/rspamd/dkim/${MAIL_DOMAIN}.mail.txt"
raw="$(docker compose exec -T rspamd cat "$record_file" 2>/dev/null)" || {
    echo "DKIM record not found in the rspamd container." >&2
    echo "Start the stack first: make up" >&2
    exit 1
}

# The rspamadm output is a parenthesized zone-file TXT record:
#   mail._domainkey IN TXT ( "v=DKIM1; k=rsa;" "p=..." ) ;
value="$(printf '%s\n' "$raw" \
    | sed -e 's/^.*(//' -e 's/).*$//' -e 's/"//g' \
    | tr '\n' ' ' \
    | sed -e 's/[[:space:]][[:space:]]*/ /g' -e 's/^ //' -e 's/ $//')"

cat <<EOF
DKIM selector: mail
DNS name:      mail._domainkey.${MAIL_DOMAIN}
Record type:   TXT
Record value:  ${value}

Raw rspamadm output:
${raw}
EOF
